const MASTER_STORAGE_KEY = 'mep_master_custom_items';

/**
 * Get all Master items merged from static data + localStorage additions/edits
 */
function getMasterItems() {
    let customItems = [];
    try {
        const saved = localStorage.getItem(MASTER_STORAGE_KEY);
        if (saved) {
            customItems = JSON.parse(saved);
        }
    } catch (e) {
        console.error("Failed to load custom master items:", e);
    }

    // Build map for fast lookup and override
    const masterMap = new Map();
    RAW_MASTER_DATA.forEach(item => masterMap.set(item.code.toUpperCase(), { ...item }));
    customItems.forEach(item => {
        if (item._deleted) {
            masterMap.delete(item.code.toUpperCase());
        } else {
            masterMap.set(item.code.toUpperCase(), { ...item });
        }
    });

    return Array.from(masterMap.values());
}

/**
 * Get single Master item by Code (Case-Insensitive)
 */
function getMasterItem(code) {
    if (!code) return null;
    const cleanCode = code.toString().trim().toUpperCase();
    const all = getMasterItems();
    return all.find(item => item.code.toUpperCase() === cleanCode) || null;
}

/**
 * Lookup Item Name by Code
 */
function getMasterName(code, defaultName = '') {
    const item = getMasterItem(code);
    return item ? item.name : (defaultName || code);
}

/**
 * Lookup Unit by Code
 */
function getMasterUnit(code, defaultUnit = 'Pcs') {
    const item = getMasterItem(code);
    return item ? item.unit : defaultUnit;
}

/**
 * Save new or update existing Master Item
 */
function saveMasterItem(newItem) {
    if (!newItem || !newItem.code) return false;
    let customItems = [];
    try {
        const saved = localStorage.getItem(MASTER_STORAGE_KEY);
        if (saved) customItems = JSON.parse(saved);
    } catch (e) {
        customItems = [];
    }

    const cleanCode = newItem.code.trim().toUpperCase();
    const existingIndex = customItems.findIndex(i => i.code.toUpperCase() === cleanCode);

    const record = {
        code: newItem.code.trim(),
        name: newItem.name.trim(),
        unit: (newItem.unit || 'Pcs').trim(),
        category: (newItem.category || 'General').trim()
    };

    if (existingIndex >= 0) {
        customItems[existingIndex] = record;
    } else {
        customItems.push(record);
    }

    localStorage.setItem(MASTER_STORAGE_KEY, JSON.stringify(customItems));
    return true;
}

/**
 * Delete Master Item by Code
 */
function deleteMasterItem(code) {
    if (!code) return false;
    let customItems = [];
    try {
        const saved = localStorage.getItem(MASTER_STORAGE_KEY);
        if (saved) customItems = JSON.parse(saved);
    } catch (e) {
        customItems = [];
    }

    const cleanCode = code.trim().toUpperCase();
    
    // Check if in base data
    const isBase = RAW_MASTER_DATA.some(i => i.code.toUpperCase() === cleanCode);
    if (isBase) {
        // Mark as deleted in customItems
        const idx = customItems.findIndex(i => i.code.toUpperCase() === cleanCode);
        if (idx >= 0) {
            customItems[idx]._deleted = true;
        } else {
            customItems.push({ code: code, _deleted: true });
        }
    } else {
        customItems = customItems.filter(i => i.code.toUpperCase() !== cleanCode);
    }

    localStorage.setItem(MASTER_STORAGE_KEY, JSON.stringify(customItems));
    return true;
}
